import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

import 'package:ecg_reader/engine/digitizer.dart';
import 'package:flutter_test/flutter_test.dart';

// Vectors are generated by validation (see validation/README or make_dart_vectors);
// they are large and not committed, so this test is skipped when they are absent.
void main() {
  final dir = Directory('test/vectors/digitizer');
  final exp = File('${dir.path}/expected.json');
  test('digitizer post-processing matches the Python reference', () {
    final cases = (jsonDecode(exp.readAsStringSync()) as List).cast<Map<String, dynamic>>();
    for (final c in cases) {
      final w = c['w'] as int, h = c['h'] as int;
      Map2D load(String k) =>
          Map2D(w, h, File('${dir.path}/${c['name']}_$k.bin').readAsBytesSync().buffer.asFloat32List());
      final res = postprocess(load('sig'), load('grid'));
      final info = c['info'] as Map<String, dynamic>;
      if (c['error'] != null) {
        // refusal case (grid not found / scale gate): the app must refuse with the same message and no leads
        expect(res.leads, isNull, reason: '${c['name']} must be refused');
        expect(res.error, c['error'], reason: c['name']);
        if (info['scale_dev'] != null) {
          expect(((res.info['scale_dev'] as double) - (info['scale_dev'] as num)).abs(), lessThan(0.005), reason: '${c['name']} scale_dev');
        }
        continue;
      }
      expect(res.error, isNull, reason: c['name']);
      expect(res.info['rotation_deg'], info['rotation_deg'], reason: '${c['name']} rotation');
      expect(((res.info['px_per_mm'] as double) / (info['px_per_mm'] as num) - 1).abs(), lessThan(0.005));
      expect(res.info['rows_y'], (info['rows_y'] as List).cast<int>(), reason: '${c['name']} rows');
      final want = (c['x'] as List).map((l) => (l as List).map((v) => v == null ? double.nan : (v as num).toDouble()).toList()).toList();
      var maxDiff = 0.0, nanMismatch = 0;
      for (var j = 0; j < 12; j++) {
        for (var i = 0; i < 1000; i++) {
          final a = res.leads![j][i], b = want[j][i];
          if (a.isNaN != b.isNaN) {
            nanMismatch++;
          } else if (!a.isNaN) {
            maxDiff = math.max(maxDiff, (a - b).abs());
          }
        }
      }
      // ignore: avoid_print
      print('${c['name']}: max |diff| ${maxDiff.toStringAsFixed(4)} mV, NaN mismatches $nanMismatch');
      expect(maxDiff, lessThan(0.05));
      expect(nanMismatch, lessThan(30));
    }
  }, skip: exp.existsSync() ? false : 'digitizer vectors not generated');
}

